API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(Entry_Router, "Entry Router", "Amazon API Gateway", "Manages entry routing, rate limiting, and initial request distribution.")
    Component(WAF_Protection, "WAF Protection", "AWS WAF", "Mitigates DDoS attacks and bot scraping to protect system uptime.")
    Component(Token_Authorizer, "Token Authorizer", "AWS Lambda Authorizers", "Performs custom token exchange, JWT validation, and claims enrichment.")
}

Rel(Entry_Router, WAF_Protection, "Filters incoming client traffic", "")
Rel(Entry_Router, Token_Authorizer, "Delegates authentication and token validation", "")

@enduml
